def transform(grid):
    out = [row[:] for row in grid]
    color = next(v for row in grid for v in row if v != 0)
    starts = (0, 3, 6, 9, 12)

    def motif(row):
        return tuple((1 if row[c] else 0) + (2 if row[c + 1] else 0)
                     for c in starts)

    # Apply the demonstrated row-pattern corrections to the matching motifs.
    mapping = {
        (1, 3, 1, 3, 1): (1, 1, 3, 1, 3),
        (3, 1, 3, 1, 1): (3, 1, 1, 1, 1),
        (3, 3, 3, 1, 1): (3, 3, 3, 3, 3),
        (3, 1, 3, 1, 3): (1, 3, 1, 3, 3),
        (1, 3, 3, 1, 3): (1, 1, 3, 1, 3),
    }
    for r in range(1, len(grid), 2):
        src = motif(grid[r])
        dst = mapping.get(src, src)
        for c, state in zip(starts, dst):
            out[r][c] = color if state & 1 else 0
            out[r][c + 1] = color if state & 2 else 0
    return out
